import * as rpc from "rage-rpc";

const NPC_ID = "car_rental";
const NPC_POS = new mp.Vector3(-194.429 , -793.410, 30.454);
const NPC_HEADING = 330;
const INTERACT_DISTANCE = 2.5;

const npc = mp.peds.new(mp.joaat("s_m_y_valet_01"), NPC_POS, {
  heading: NPC_HEADING,
  dimension: 0,
  dynamic: false,
  invincible: true,
  frozen: true,
});
npc.setVariable("npcId", NPC_ID);
npc.setVariable("invincibleNpc", true);

mp.labels.new("Оренда авто", new mp.Vector3(NPC_POS.x, NPC_POS.y, NPC_POS.z + 1.1), {
  font: 4,
  color: [255, 255, 255, 255],
  drawDistance: 15,
  los: false,
  dimension: 0,
});

rpc.register("npc:interact", (data: { npcId?: string; action?: string }, info: rpc.ProcedureListenerInfo) => {
  const player = info.player as PlayerMp | undefined;
  if (!player || !mp.players.exists(player) || player.dimension !== 0) {
    return { success: false, message: "Взаимодействие недоступно." };
  }

  if (data?.npcId !== NPC_ID) return { success: false, message: "Неизвестный NPC." };

  const dx = player.position.x - NPC_POS.x;
  const dy = player.position.y - NPC_POS.y;
  const dz = player.position.z - NPC_POS.z;
  if (dx * dx + dy * dy + dz * dz > INTERACT_DISTANCE * INTERACT_DISTANCE) {
    return { success: false, message: "Подойдите ближе к парковщику." };
  }

  if (data.action === "rent") {
    return { success: true, message: "Меню аренды авто открыто" };
  }

  return { success: true, message: "" };
});
